import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const n="/assets/blocks-for-ha/grid/en/light.png",i="/assets/blocks-for-ha/grid/en/dark.png",s="/assets/blocks-for-ha/themes/en/dark.png",l="/assets/blocks-for-ha/themes/en/tritanopia.png",u=JSON.parse('{"title":"Themes and zoom","description":"Saved theme selection and an additional fit control in the Blockly editor.","frontmatter":{"title":"Themes and zoom","description":"Saved theme selection and an additional fit control in the Blockly editor."},"headers":[],"relativePath":"en/projects/blocks-for-ha/themes.md","filePath":"en/projects/blocks-for-ha/themes.md","lastUpdated":1793128957000}'),d={name:"en/projects/blocks-for-ha/themes.md"};function c(h,e,p,g,m,b){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="themes-and-zoom" tabindex="-1">Themes and zoom <a class="header-anchor" href="#themes-and-zoom" aria-label="Permalink to &quot;Themes and zoom&quot;">​</a></h1><h2 id="logic-and-objects-since-0-1-56" tabindex="-1">Logic and Objects since 0.1.56 <a class="header-anchor" href="#logic-and-objects-since-0-1-56" aria-label="Permalink to &quot;Logic and Objects since 0.1.56&quot;">​</a></h2><p>In Standard/Dark, logic blocks are blue and object blocks brown, with readable white labels. Modern and Tritanopia retain their own palettes. <strong>If / else if / else</strong> is now directly available in <strong>Logic</strong>: the gear opens the branch builder; additional branches and Else are added or removed there. Conditions and action sequences produce native HA branching. Existing projects remain compatible.</p><h2 id="dot-grid-since-0-1-51" tabindex="-1">Dot grid since 0.1.51 <a class="header-anchor" href="#dot-grid-since-0-1-51" aria-label="Permalink to &quot;Dot grid since 0.1.51&quot;">​</a></h2><p>The workspace has a clear native Blockly dot grid with 25-unit spacing and snapping, inspired by <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/BlocklyEditor.tsx" target="_blank" rel="noreferrer">ioBroker&#39;s Blockly editor</a>. The background and dots immediately follow <strong>Light / Dark / System</strong> app appearance, including changes to the system setting. The Blockly selector still determines block and menu colours; workspace appearance follows the app even with the Dark palette.</p><p>Zooming and panning move the grid with the workspace. Fit does not resize palette blocks. Appearance and palette do not change the automation or YAML.</p><p><img src="'+n+'" alt="Light dot grid"></p><p><img src="'+i+'" alt="Dark dot grid"></p><p>Since <strong>0.1.27</strong>, UGSo blocks in Standard/Dark use white labels. Medium blue and brown backgrounds are slightly darker to provide at least <strong>4.5:1</strong> contrast. Original light Modern/Tritanopia colours use sufficiently contrasting dark labels. Editable fields retain separate readable surfaces. The DE/EN/FR catalog images have been regenerated with this correction.</p><p>Since <strong>0.1.16</strong>, the toolbar above the workspace includes a <strong>Theme selector</strong>. It affects Blockly categories, flyouts and blocks. The Blockly palette is independent of the app appearance. There are still 111 block types.</p><table tabindex="0"><thead><tr><th>Choice</th><th>Appearance</th><th>Upstream source</th></tr></thead><tbody><tr><td>UGSo Standard</td><td>Existing UGSo group colours, dark menu and light flyout</td><td>Own UGSo adaptation based on Blockly Classic</td></tr><tr><td>Dark</td><td>Dark workspace and flyout, with a distinct category-menu background</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-dark" target="_blank" rel="noreferrer">theme-dark</a></td></tr><tr><td>Modern</td><td>Original Modern palette with stronger borders and UGSo extension groups</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-modern" target="_blank" rel="noreferrer">theme-modern</a></td></tr><tr><td>Tritanopia</td><td>Original standard-group palette plus colours for HA-specific groups</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-tritanopia" target="_blank" rel="noreferrer">theme-tritanopia</a></td></tr></tbody></table><p>Tritanopia is intended for people with this colour-vision deficiency. Own UGSo blocks and categories now use theme styles instead of fixed colours. Light blocks get dark labels, dark blocks light labels; editable fields remain separately readable. Selected categories have a dark background and light text across palettes. Category names and block labels remain available for orientation. This does not certify complete accessibility.</p><p><img src="'+s+'" alt="Dark in the UGSo editor"></p><p><img src="'+l+'" alt="Tritanopia in the UGSo editor"></p><h2 id="switching-and-saving" tabindex="-1">Switching and saving <a class="header-anchor" href="#switching-and-saving" aria-label="Permalink to &quot;Switching and saving&quot;">​</a></h2><p>Themes switch immediately without rebuilding the workspace. Blocks, connections, positions and YAML remain intact. The choice is saved separately from the project in this browser and restored after reload. Project files and YAML do not transfer this display preference to another browser. Unknown preferences fall back to UGSo Standard; when browser storage is blocked, switching still works for the current session.</p><p>The existing <strong>Geras renderer</strong> remains active for all themes, preserving connection geometry and controls. Upstream Modern recommends Zelos/Thrasos; here its colour/border palette is used and checked with Geras. Renderer selection is not an additional option in this version.</p><h2 id="fit-all-blocks" tabindex="-1">Fit all blocks <a class="header-anchor" href="#fit-all-blocks" aria-label="Permalink to &quot;Fit all blocks&quot;">​</a></h2><p>Original <a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/zoom-to-fit" target="_blank" rel="noreferrer">zoom-to-fit</a> adds the four-arrow icon next to the zoom controls. Clicking fits blocks to the available workspace. The control is reachable with Tab and works with Enter/Space. Zoom changes the view, not the automation.</p><p>Since <strong>0.1.40</strong>, all themes use <strong>16 px block text</strong>. The block menu stays at <strong>100%</strong>: fitting, mouse wheel and zoom controls affect only the workspace. Initial zoom 100%, fitting 85–120%, manual zoom 50–240%. Large automations remain scrollable; fitting never shrinks below 85% to preserve readability. Verified at Full HD, 2560 px and HiDPI.</p><p>All four additional original plugins are pinned to <strong>13.3.0</strong>, integrated with Blockly <strong>13.3.0</strong>, and licensed under Apache-2.0. The six existing plugins remain on 13.2.0. Packages are bundled locally without external theme files or CDN dependencies. Upstream links and notices are also in the <a href="./blocks">block catalog</a>.</p><p>Verified: four themes, labels on light Tritanopia blocks, unchanged project/YAML output, saved choice, unknown/blocked storage preferences, fitting and mobile width. This display change does not alter HA execution.</p><h2 id="app-appearance-light-dark-or-system" tabindex="-1">App appearance: Light, Dark or System <a class="header-anchor" href="#app-appearance-light-dark-or-system" aria-label="Permalink to &quot;App appearance: Light, Dark or System&quot;">​</a></h2><p>Since <strong>0.1.22</strong>, <strong>Darstellung</strong> in the header offers <strong>Hell</strong> (Light), <strong>Dunkel</strong> (Dark) and <strong>System</strong> for the entire surrounding application: header, panels, forms, YAML output, dialogs, entity selection and the custom block/template editor. System is the default and follows changes to the operating-system/browser colour preference immediately. A manual choice overrides the system setting. The preference is saved locally in this browser; if browser storage is unavailable, switching still works for the current page.</p><p>Blockly themes remain independently selectable in the workspace toolbar, including Modern and Tritanopia. Appearance changes do not alter blocks, generated YAML or projects. The original Built-with-Blockly badge automatically uses the matching light/dark variant.</p>',25)])])}const f=t(d,[["render",c]]);export{u as __pageData,f as default};
